import { NavLink, Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { useCart } from '../context/CartContext';

const linkClass = ({ isActive }) =>
  'text-sm transition ' + (isActive ? 'font-medium text-amber-600' : 'text-slate-500 hover:text-amber-600');

function Navbar() {
  const { isLoggedIn, isAdmin, member, logout } = useAuth();
  const { totalCount } = useCart();
  const navigate = useNavigate();

  function handleLogout() {
    logout();
    navigate('/');
  }

  return (
    <header className="border-b border-amber-100 bg-white sticky top-0 z-30">
      <nav className="mx-auto flex max-w-5xl flex-wrap items-center gap-x-6 gap-y-2 px-4 py-4 md:px-6">
        <Link to="/" className="text-lg font-semibold tracking-tight text-amber-700">
          📚 NangSuKub
        </Link>
        <div className="flex items-center gap-5">
          <NavLink to="/" end className={linkClass}>หน้าแรก</NavLink>
          <NavLink to="/books" className={linkClass}>หนังสือ</NavLink>
          {isLoggedIn && (
            <>
              <NavLink to="/cart" className={({ isActive }) => `${linkClass({ isActive })} flex items-center gap-1`}>
                <span>🛒 ตะกร้า</span>
                {totalCount > 0 && (
                  <span className="inline-flex h-5 min-w-[20px] items-center justify-center rounded-full bg-amber-500 px-1.5 text-xs font-bold text-white">
                    {totalCount}
                  </span>
                )}
              </NavLink>
              <NavLink to="/me/wishlist" className={linkClass}>อยากอ่าน</NavLink>
            </>
          )}
          <NavLink to="/about" className={linkClass}>เกี่ยวกับ</NavLink>
          {isAdmin && <NavLink to="/admin" className={linkClass}>หลังบ้าน</NavLink>}
        </div>
        <div className="ml-auto flex items-center gap-3 text-sm">
          {isLoggedIn ? (
            <>
              <span className="text-slate-600">สวัสดี {member?.displayName}</span>
              <button onClick={handleLogout} className="text-slate-500 hover:text-amber-600">ออกจากระบบ</button>
            </>
          ) : (
            <Link to="/login" className="rounded-lg border border-amber-200 bg-white px-3 py-1.5 text-amber-700 hover:bg-amber-50">
              เข้าสู่ระบบ
            </Link>
          )}
        </div>
      </nav>
    </header>
  );
}

export default Navbar;
